    '/24-strand-climbing-rope/yale-new-moon-11-7mm-climbing-rope/' => 
    array (
      'path' => '/24-strand-climbing-rope/yale-new-moon-11-7mm-climbing-rope/',
      'category' => '/rope/climbing-rope/24-strand-climbing-rope/',
      'name' => 'Yale New Moon 11.7mm Climbing Rope',
