    '/blowers-and-other-equipment/husqvarna-560bts-65cc-backpack-blower/' => 
    array (
      'path' => '/blowers-and-other-equipment/husqvarna-560bts-65cc-backpack-blower/',
      'category' => '/jobsite/power-equipment/blowers-and-other-equipment/',
