    '/chainsaw-lanyards/ring-and-ring-bungee-chainsaw-lanyard/' => 
    array (
      'path' => '/chainsaw-lanyards/ring-and-ring-bungee-chainsaw-lanyard/',
      'category' => '/climbing/climbing-gear/chainsaw-lanyards/',
      'name' => 'Ring and Ring Bungee Chainsaw Lanyard',
