    '/climbing/climbing-gear/ascent-and-descent/foot-ascenders-and-foot-loops/edelrid-talon-tree-cruiser/' => 
    array (
      'path' => '/climbing/climbing-gear/ascent-and-descent/foot-ascenders-and-foot-loops/edelrid-talon-tree-cruiser/',
