    '/climbing/climbing-gear/carabiners-and-hardware/non-locking-carabiners/kong-oval-classic-steel-straight-gate-carabiner/' => 
    array (
      'path' => '/climbing/climbing-gear/carabiners-and-hardware/non-locking-carabiners/kong-oval-classic-steel-straight-gate-carabiner/',
      'category' => '/climbing/climbing-gear/carabiners-and-hardware/non-locking-carabiners/',
