    '/climbing/saddles-and-harnesses/european-saddles/husqvarna-climbing-harness/' => 
    array (
      'path' => '/climbing/saddles-and-harnesses/european-saddles/husqvarna-climbing-harness/',
      'category' => '/climbing/saddles-and-harnesses/european-saddles/',
