    '/climbing/spurs/klein-steel-climbers/klein-climbers-with-big-buck-pads/' => 
    array (
      'path' => '/climbing/spurs/klein-steel-climbers/klein-climbers-with-big-buck-pads/',
      'category' => '/climbing/spurs/',
      'name' => 'Klein Climbers with Big Buck Pads',
