    '/climbing/spurs/replacement-gaffs-and-parts/climb-right-steel-height-adjustment-sleeve-and-screws/' => 
    array (
      'path' => '/climbing/spurs/replacement-gaffs-and-parts/climb-right-steel-height-adjustment-sleeve-and-screws/',
      'category' => '/climbing/spurs/replacement-gaffs-and-parts/',
