    '/climbing/spurs/replacement-gaffs-and-parts/distel-eye-bolt-m8x11/' => 
    array (
      'path' => '/climbing/spurs/replacement-gaffs-and-parts/distel-eye-bolt-m8x11/',
      'category' => '/climbing/spurs/replacement-gaffs-and-parts/',
