    '/climbing/spurs/replacement-gaffs-and-parts/replacement-gaffs-for-tree-hog-aluminum-climbers/' => 
    array (
      'path' => '/climbing/spurs/replacement-gaffs-and-parts/replacement-gaffs-for-tree-hog-aluminum-climbers/',
