    '/clothing/tree-climbing-pants/clogger-spider-pants-contrast-color/' => 
    array (
      'path' => '/clothing/tree-climbing-pants/clogger-spider-pants-contrast-color/',
      'category' => '/clothing/tree-climbing-pants/',
      'name' => 'Clogger Spider Pants, Contrast Color',
