    '/cutting-and-pruning/blades/fanno-17-tri-edge-blade/' => 
    array (
      'path' => '/cutting-and-pruning/blades/fanno-17-tri-edge-blade/',
      'category' => '/cutting-and-pruning/blades/',
      'name' => 'Fanno 17" Tri-Edge Pole Saw Blade',
      'brand' => 'fanno',
      'brand_name' => 'Fanno',
      'kind' => 'pole-saw',
      'price' => 39,
      'keyword' => 'fanno 17 tri-edge blade',
      'title' => 'Fanno 17" Tri-Edge Blade for Pole Saws',
      'h1' => 'Fanno 17" Tri-Edge Blade',
      'meta' => 'The Fanno 17 inch tri-edge blade is a fast-cutting replacement for pole saw heads. Fit, cutting feel and how to swap and care for it on the job.',
      'tagline' => 'A 17-inch tri-edge replacement blade for pruning pole saws.',
      'summary' => 'This Fanno 17" tri-edge blade is a replacement blade for pole saw heads. Tri-edge teeth cut on the pull stroke and clear chips well, so it moves quickly through green limbs overhead.',
      'highlights' => 
      array (
        0 => '17-inch blade length',
        1 => 'Tri-edge teeth for fast pull cuts',
        2 => 'Replacement for pole saw heads',
        3 => 'Made by Fanno, a US saw maker',
        4 => 'Good for green wood overhead',
      ),
      'specs' => 
      array (
        0 => 
        array (
          0 => 'Blade length',
          1 => '17 in',
        ),
        1 => 
        array (
          0 => 'Tooth style',
          1 => 'Tri-edge',
        ),
        2 => 
        array (
          0 => 'Cutting stroke',
          1 => 'Pull',
        ),
        3 => 
        array (
          0 => 'Use',
          1 => 'Pole saw replacement blade',
        ),
      ),
      'body' => 
      array (
        0 => 
        array (
          'h' => 'A fresh edge for your pole saw',
          'p' => 
          array (
            0 => 'A dull pole saw blade turns a clean pruning cut into a fight, and on a pole every extra stroke is wasted effort at arm\'s length. The Fanno 17-inch tri-edge blade gives you a new set of teeth for your pole saw head. Tri-edge teeth are ground on three faces, cut on the pull and clear sawdust well in green wood.',
            1 => 'Before ordering, check that the mounting holes and blade length match your saw head. More replacement blades are listed in our <a href="/cutting-and-pruning/blades/">blades</a> section.',
            2 => 'Many crews keep a spare blade in the truck so a dull or kinked one never stops a pruning job.',
          ),
        ),
        1 => 
        array (
          'h' => 'Swapping and care',
          'p' => 
          array (
            0 => 'Replace the blade when teeth are dull, bent or broken, or when the blade has a kink. Swap it on the ground with the pole laid down. Wear gloves when you handle a bare blade, keep it in a scabbard or cover when it is not in use, and never cut toward your body or your lanyard.',
            1 => 'Wipe off sap after use and keep the blade dry to prevent rust. Never use a pole saw near energized power lines unless you are a trained, qualified line-clearance arborist with the right equipment, and keep the minimum approach distances in ANSI Z133.',
          ),
        ),
      ),
      'faq' => 
      array (
        0 => 
        array (
          'q' => 'Will this blade fit my pole saw?',
          'a' => 'It fits pole saw heads made for a 17-inch blade with matching mounting holes. Check your head before ordering.',
        ),
        1 => 
        array (
          'q' => 'Can I sharpen a tri-edge blade?',
          'a' => 'Tri-edge teeth are usually hardened and hard to file well. Most crews replace the blade when it dulls.',
        ),
      ),
      'use' => 
      array (
        0 => 'pruning',
      ),
      'level' => 'all',
      'brand_path' => '/fanno/',
      'photo' => 
      array (
        'src' => '/assets/photos/pole-saw-1.webp',
        'sm' => '/assets/photos/pole-saw-1-sm.webp',
        'title' => '2009. Lorraine MacLauchlan (B.C. Ministry of Forests, Southern Interior Region) with pole-pruner to sample Douglas-fir tussock moth larvae, pre-spray. Testing the effectiveness of low-dose application rates of TM-Biocontrol-1. Kamloops, B.C.',
        'creator' => 'USDA Forest Service',
        'creator_url' => 'https://www.flickr.com/photos/151887236@N05',
        'license' => 'Public domain',
        'license_url' => 'https://creativecommons.org/publicdomain/mark/1.0/',
        'source_url' => 'https://www.flickr.com/photos/151887236@N05/39161789941',
      ),
    ),
    '/cutting-and-pruning/blades/jameson-16-tri-cut-saw-blade/' => 
    array (
      'path' => '/cutting-and-pruning/blades/jameson-16-tri-cut-saw-blade/',
      'category' => '/cutting-and-pruning/blades/',
      'name' => 'Jameson 16" Tri-Cut Saw Blade',
      'brand' => 'jameson',
      'brand_name' => 'Jameson',
      'kind' => 'pole-saw',
      'price' => 29,
      'keyword' => 'jameson 16 tri-cut saw blade',
      'title' => 'Jameson 16" Tri-Cut Saw Blade for Pole Saws',
      'h1' => 'Jameson 16" Tri-Cut Saw Blade',
      'meta' => 'The Jameson 16 inch tri-cut saw blade is a replacement pole saw blade for Jameson heads, built for fast pull cuts in green wood. Fit, use and care.',
      'tagline' => 'A 16-inch tri-cut replacement blade for Jameson pole saw heads.',
      'summary' => 'This Jameson 16" tri-cut saw blade is a replacement for Jameson pole saw heads. The tri-cut teeth cut on the pull stroke and move quickly through green limbs when you are pruning from the ground.',
      'highlights' => 
      array (
        0 => '16-inch blade length',
        1 => 'Tri-cut teeth for fast pull cuts',
        2 => 'Replacement for Jameson pole saw heads',
        3 => 'Cuts green wood cleanly',
        4 => 'Inexpensive to swap when dull',
      ),
      'specs' => 
      array (
        0 => 
        array (
          0 => 'Blade length',
          1 => '16 in',
        ),
        1 => 
        array (
          0 => 'Tooth style',
          1 => 'Tri-cut',
        ),
        2 => 
        array (
          0 => 'Cutting stroke',
          1 => 'Pull',
        ),
        3 => 
        array (
          0 => 'Use',
          1 => 'Pole saw replacement blade',
        ),
      ),
      'body' => 
      array (
        0 => 
        array (
          'h' => 'Keep your Jameson head cutting',
          'p' => 
          array (
            0 => 'Jameson pole saws are common on tree crews and utility trucks, and the blade is the part that wears out. A fresh 16-inch tri-cut blade brings back fast, clean cuts. The teeth cut on the pull, which is the natural stroke when you are working overhead from the ground.',
            1 => 'Check that the blade length and mounting pattern match your saw head before you order. More options are in our <a href="/cutting-and-pruning/blades/">blades</a> section.',
            2 => 'Blades are cheap compared with the time lost sawing with a dull one, so many crews keep a spare in the truck and swap at the first sign of slow cutting or drift.',
          ),
        ),
        1 => 
        array (
          'h' => 'Swapping and care',
          'p' => 
          array (
            0 => 'Change the blade on the ground with the pole laid flat. Replace it when teeth are dull, missing or bent, or if the blade is kinked from a pinch. Wear gloves when you handle a bare blade, keep it in a scabbard or cover when it is not in use, and never cut toward your body or your lanyard.',
            1 => 'Clean off sap and keep the blade dry. Never use a pole saw near energized power lines unless you are a trained, qualified line-clearance arborist with the right equipment, and keep the minimum approach distances in ANSI Z133.',
          ),
        ),
      ),
      'faq' => 
      array (
        0 => 
        array (
          'q' => 'Does this blade fit non-Jameson saw heads?',
          'a' => 'It is made for Jameson heads. Other heads may use different lengths or hole patterns, so compare before buying.',
        ),
        1 => 
        array (
          'q' => 'When should I replace a pole saw blade?',
          'a' => 'When it cuts slowly, drifts in the cut, or has bent, broken or missing teeth.',
        ),
      ),
      'use' => 
      array (
        0 => 'pruning',
      ),
      'level' => 'all',
      'brand_path' => '/jameson/',
      'photo' => 
      array (
        'src' => '/assets/photos/pole-saw-2.webp',
        'sm' => '/assets/photos/pole-saw-2-sm.webp',
        'title' => '1974. Colville field crew checking tussock moth populations. Douglas-fir tussock moth control project. Grand Coulee Dam Headquarters, Colville Reservation, Washington.',
        'creator' => 'USDA Forest Service',
        'creator_url' => 'https://www.flickr.com/photos/151887236@N05',
        'license' => 'Public domain',
        'license_url' => 'https://creativecommons.org/publicdomain/mark/1.0/',
        'source_url' => 'https://www.flickr.com/photos/151887236@N05/35679281040',
      ),
