    '/cutting-and-pruning/blades/silky-hayate-390mm-xl-teeth-replacement-blade-blade-only/' => 
    array (
      'path' => '/cutting-and-pruning/blades/silky-hayate-390mm-xl-teeth-replacement-blade-blade-only/',
      'category' => '/cutting-and-pruning/blades/',
      'name' => 'Silky Hayate 390mm XL Teeth Replacement Blade',
      'brand' => 'silky',
      'brand_name' => 'Silky',
