    '/cutting-and-pruning/hand-saws-and-scabbards/jameson-11-straight-blade-hand-saw/' => 
    array (
      'path' => '/cutting-and-pruning/hand-saws-and-scabbards/jameson-11-straight-blade-hand-saw/',
      'category' => '/cutting-and-pruning/hand-saws-and-scabbards/',
      'name' => 'Jameson 11" Straight Blade Hand Saw',
      'brand' => 'jameson',
