    '/cutting-and-pruning/parts-and-accessories/silky-elastic-leg-straps/' => 
    array (
      'path' => '/cutting-and-pruning/parts-and-accessories/silky-elastic-leg-straps/',
      'category' => '/cutting-and-pruning/poles-and-kits/',
      'name' => 'Silky Elastic Leg Straps',
      'brand' => 'silky',
      'brand_name' => 'Silky',
      'kind' => 'case-bag',
      'price' => 15,
      'keyword' => 'silky elastic leg straps',
      'title' => 'Silky Elastic Leg Straps for Saw Scabbards',
      'h1' => 'Silky Elastic Leg Straps',
      'meta' => 'Silky elastic leg straps hold a long saw scabbard against your thigh so it doesn\'t swing or snag while climbing, walking brush or working off a ladder.',
      'tagline' => 'Elastic thigh straps that keep a long Silky scabbard from swinging.',
      'summary' => 'Silky elastic leg straps hold the bottom of a saw scabbard against your thigh. On longer saws the scabbard tip swings, catches on brush and slaps your leg, and a leg strap stops that.',
      'highlights' => 
      array (
