    '/eye-and-eye-prusiks/yale-veritas-8mm-sewn-eye-to-eye/' => 
    array (
      'path' => '/eye-and-eye-prusiks/yale-veritas-8mm-sewn-eye-to-eye/',
      'category' => '/climbing/climbing-gear/hitch-cord-and-split-tails/eye-and-eye-prusiks/',
      'name' => 'Yale Veritas 8mm Sewn Eye-to-Eye Hitch Cord',
      'brand' => 'yale-cordage',
      'brand_name' => 'Yale Cordage',
      'kind' => 'rope',
