    '/gear-bags/camp-spacecraft-45-l/' => 
    array (
      'path' => '/gear-bags/camp-spacecraft-45-l/',
      'category' => '/climbing/climbing-gear/gear-storage/gear-bags/',
      'name' => 'CAMP Spacecraft 45 L Gear Bag',
