    '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/husqvarna-3-8-x-50-professional-chainsaw-bar/' => 
    array (
      'path' => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/husqvarna-3-8-x-50-professional-chainsaw-bar/',
      'category' => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/',
      'name' => 'Husqvarna 3/8 x .050 Professional Chainsaw Bar',
      'brand' => 'husqvarna',
      'brand_name' => 'Husqvarna',
      'kind' => 'chain-bar',
      'price' => 75,
      'keyword' => 'husqvarna 3/8 chainsaw bar',
      'title' => 'Husqvarna 3/8 Chainsaw Bar, .050 Gauge, Professional',
      'h1' => 'Husqvarna 3/8 x .050 Professional Chainsaw Bar',
      'meta' => 'Husqvarna 3/8 chainsaw bar in .050 gauge for mid to large pro saws. Replaceable sprocket nose design, built for felling, bucking and daily tree work.',
      'tagline' => 'Pro replacement bar in 3/8 pitch, .050 gauge for mid to large Husqvarna saws.',
      'summary' => 'This Husqvarna 3/8 chainsaw bar in .050 gauge is a professional replacement for mid to large saws used on removals, felling and bucking. Match the pitch, gauge, length and mount to your saw before ordering.',
      'highlights' => 
      array (
        0 => '3/8 in pitch, .050 in gauge',
        1 => 'Professional-grade construction',
        2 => 'For mid to large Husqvarna saws',
        3 => 'Built for daily felling and bucking',
        4 => 'Run with matching 3/8 x .050 chain',
      ),
      'specs' => 
      array (
        0 => 
        array (
          0 => 'Pitch',
          1 => '3/8 in',
        ),
        1 => 
        array (
          0 => 'Gauge',
          1 => '.050 in',
        ),
        2 => 
        array (
          0 => 'Brand',
          1 => 'Husqvarna',
        ),
      ),
      'body' => 
      array (
        0 => 
        array (
          'h' => 'Matching the bar to your saw',
          'p' => 
          array (
            0 => 'A bar has to match three things: the saw\'s mount pattern, the chain pitch and the chain gauge. This bar runs 3/8 in pitch chain in .050 in gauge, a common pairing on mid-size and larger professional saws. Choose a length that suits the saw\'s power. A bar that is too long for the powerhead slows the chain in the cut and works the saw harder.',
            1 => 'Count the drive links on your current chain or check the stamp on your old bar to get the length and chain right.',
            2 => 'A professional-grade bar is built for daily use, with rails hardened to hold up and a nose made to take the load of long cutting days. If you run several saws, keep spare bars for each one, so a pinched or bent bar does not end the day early. Look at the drive sprocket and chain at the same time, since all three wear together.',
          ),
        ),
        1 => 
        array (
          'h' => 'Bar care',
          'p' => 
          array (
            0 => 'Flip the bar each time you sharpen so the rails wear evenly, clean the groove and oil holes, and dress burrs off the rails with a flat file. Keep the oiler set so the chain throws a light mist when run against a stump. A pinched groove or blued rails mean the bar needs attention.',
            1 => 'More bars and chain are in our <a href="/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/">chainsaw bars</a> section.',
          ),
        ),
      ),
      'faq' => 
      array (
        0 => 
        array (
          'q' => 'Will this fit my saw?',
          'a' => 'Check your saw\'s bar mount and the length you need. Husqvarna bars are listed by mount, pitch and gauge, and all three must match.',
        ),
        1 => 
        array (
          'q' => 'What chain goes on this bar?',
          'a' => 'A 3/8 in pitch, .050 in gauge chain with the correct drive link count for the bar length.',
        ),
      ),
      'use' => 
      array (
        0 => 'felling',
        1 => 'ground',
        2 => 'maintenance',
      ),
      'level' => 'pro',
      'brand_path' => '/husqvarna/',
      'photo' => 
      array (
        'src' => '/assets/photos/chain-bar-0.webp',
        'sm' => '/assets/photos/chain-bar-0-sm.webp',
        'title' => 'Cutting Edge',
        'creator' => 'Clint__Budd',
        'creator_url' => 'https://www.flickr.com/photos/58827557@N06',
        'license' => 'CC BY 2.0',
        'license_url' => 'https://creativecommons.org/licenses/by/2.0/',
        'source_url' => 'https://www.flickr.com/photos/58827557@N06/49188576927',
      ),
    ),
    '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/husqvarna-sprocket-nose-chainsaw-bar-404/' => 
    array (
      'path' => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/husqvarna-sprocket-nose-chainsaw-bar-404/',
      'category' => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/',
      'name' => 'Husqvarna .404 Sprocket Nose Chainsaw Bar',
      'brand' => 'husqvarna',
      'brand_name' => 'Husqvarna',
      'kind' => 'chain-bar',
      'price' => 130,
      'keyword' => 'husqvarna sprocket nose bar',
      'title' => 'Husqvarna Sprocket Nose Bar for .404 Chain',
      'h1' => 'Husqvarna .404 Sprocket Nose Chainsaw Bar',
      'meta' => 'A Husqvarna sprocket nose bar for .404 chain on big saws and heavy wood. Built for felling and bucking large trees. Check the mount and length first.',
      'tagline' => 'Heavy-duty sprocket nose bar for big saws running .404 pitch chain.',
      'summary' => 'This Husqvarna sprocket nose bar for .404 pitch chain keeps the chain moving freely around the tip on big saws. It is built for felling and bucking large wood where .404 pitch chain is the norm.',
      'highlights' => 
      array (
        0 => '.404 in pitch for large saws',
        1 => 'Sprocket nose reduces friction at the tip',
        2 => 'Built for heavy felling and bucking',
        3 => 'For large-displacement professional saws',
        4 => 'Pair with matching .404 chain',
      ),
      'specs' => 
      array (
        0 => 
        array (
          0 => 'Pitch',
          1 => '.404 in',
        ),
        1 => 
        array (
          0 => 'Nose',
          1 => 'Sprocket nose',
        ),
        2 => 
        array (
          0 => 'Brand',
          1 => 'Husqvarna',
        ),
      ),
      'body' => 
      array (
        0 => 
        array (
          'h' => 'When .404 makes sense',
          'p' => 
          array (
            0 => '.404 pitch chain is bigger and tougher than 3/8 and is run on large saws cutting big wood: felling large removals, bucking trunk sections, and slabbing. A sprocket nose lets the chain roll around the tip instead of dragging, which keeps chain speed up and heat down on long bars. It is the setup you see on high-displacement saws.',
            1 => 'Check the gauge and drive link count on your current chain, along with your saw\'s mount, before ordering.',
            2 => 'Sprocket nose bars are also easier on chain at the tip, which matters in big wood where long cuts keep the chain loaded for minutes at a time. If you are buying a new bar, it is a good time to buy fresh chain and a new drive sprocket so everything starts out matched.',
          ),
        ),
        1 => 
        array (
          'h' => 'Keeping it running',
          'p' => 
          array (
            0 => 'Grease the nose sprocket through the hole as the maker directs, flip the bar regularly, and keep the oil holes and groove clean. Replace the drive sprocket on the saw when you replace chain often, since a worn sprocket chews up new chain and bar rails. Felling with large saws should be done by trained operators in proper PPE.',
            1 => 'Retire a bar with a cracked nose, spread rails or a bend you cannot correct.',
            2 => 'See our <a href="/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/">chainsaw bars</a> for other pitches and lengths.',
          ),
        ),
      ),
      'faq' => 
      array (
        0 => 
        array (
          'q' => 'Can I run .404 on a mid-size saw?',
          'a' => '.404 is generally meant for large saws. Use the pitch your saw\'s maker specifies for its drive sprocket.',
        ),
        1 => 
        array (
          'q' => 'Does a sprocket nose need maintenance?',
          'a' => 'Yes. Grease it regularly and check for a loose or worn sprocket.',
        ),
      ),
      'use' => 
      array (
        0 => 'felling',
        1 => 'ground',
      ),
      'level' => 'pro',
      'brand_path' => '/husqvarna/',
      'photo' => 
      array (
        'src' => '/assets/photos/chain-bar-1.webp',
        'sm' => '/assets/photos/chain-bar-1-sm.webp',
        'title' => '2021/365/233 New Tools Are Fun',
        'creator' => 'cogdogblog',
        'creator_url' => 'https://www.flickr.com/photos/37996646802@N01',
        'license' => 'CC0',
        'license_url' => 'https://creativecommons.org/publicdomain/zero/1.0/',
        'source_url' => 'https://www.flickr.com/photos/37996646802@N01/51432183709',
      ),
    ),
    '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/husqvarna-x-force-narrow-kerf-pixel-chainsaw-bar-325-x-050/' => 
    array (
      'path' => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/husqvarna-x-force-narrow-kerf-pixel-chainsaw-bar-325-x-050/',
      'category' => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/',
      'name' => 'Husqvarna X-Force Narrow Kerf Pixel Chainsaw Bar .325 x .050',
      'brand' => 'husqvarna',
      'brand_name' => 'Husqvarna',
      'kind' => 'chain-bar',
      'price' => 60,
      'keyword' => 'husqvarna x-force pixel bar',
      'title' => 'Husqvarna X-Force Pixel Bar .325 x .050',
      'h1' => 'Husqvarna X-Force Narrow Kerf Pixel Chainsaw Bar .325 x .050',
      'meta' => 'Husqvarna X-Force Pixel bar in .325 x .050 narrow kerf. Pairs with Pixel chain to cut a thinner kerf, so mid-size saws cut faster with less effort.',
      'tagline' => 'Narrow kerf X-Force bar for Husqvarna\'s Pixel chain on mid-size saws.',
      'summary' => 'The Husqvarna X-Force Pixel bar is a narrow kerf bar designed for Pixel chain in .325 pitch. Removing less wood per cut lets a mid-size saw pull a bar faster and with less effort.',
      'highlights' => 
      array (
        0 => 'Made for Husqvarna Pixel narrow kerf chain',
        1 => '.325 pitch, .050 gauge (per listing)',
        2 => 'Narrow kerf means less wood removed',
        3 => 'Helps mid-size saws cut faster',
        4 => 'X-Force design from Husqvarna',
      ),
      'specs' => 
      array (
        0 => 
        array (
          0 => 'Pitch',
          1 => '.325 in (Pixel)',
        ),
        1 => 
        array (
          0 => 'Gauge',
          1 => '.050 in',
        ),
        2 => 
        array (
          0 => 'Kerf',
          1 => 'Narrow',
        ),
        3 => 
        array (
          0 => 'Brand',
          1 => 'Husqvarna',
        ),
      ),
      'body' => 
      array (
        0 => 
        array (
          'h' => 'What narrow kerf does',
          'p' => 
          array (
            0 => 'Narrow kerf chain has smaller cutters and a thinner cut, so the saw removes less wood with each pass. On a mid-size saw that means a faster cut and less load on the engine, which you notice during a long day of bucking brush wood and limbing. Pixel chain only runs on a bar and sprocket built for it, so the bar, chain and drive sprocket must all match.',
            1 => 'Confirm the sprocket on your saw is the Pixel type before switching from standard .325.',
            2 => 'For crews that run several saws, Pixel bars and chain also mean one more set of parts to keep straight, so label spare bars and chain loops clearly. The payoff is a mid-size saw that feels livelier in the cut. Keep the oiler working and the bar groove clean, since narrow kerf chain is less forgiving of a dry bar.',
          ),
        ),
        1 => 
        array (
          'h' => 'Bar care and chain',
          'p' => 
          array (
            0 => 'Flip the bar each sharpening, clean the groove, and keep oil holes open. Sharpen Pixel chain with the file size Husqvarna specifies for it. A standard .325 file is too big. Keep a spare chain in the truck so you are not touching up a dull one in the field.',
            1 => 'Browse more options in our <a href="/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-bars/">chainsaw bars</a> section.',
          ),
        ),
      ),
      'faq' => 
      array (
        0 => 
        array (
          'q' => 'Can I run standard .325 chain on a Pixel bar?',
          'a' => 'No. Pixel narrow kerf bars and chain are a matched system. Use Pixel chain and the matching drive sprocket.',
        ),
        1 => 
        array (
          'q' => 'Which saws take Pixel bars?',
          'a' => 'Mid-size Husqvarna saws set up for Pixel. Check your saw\'s manual or the bar\'s fitment listing.',
        ),
      ),
      'use' => 
      array (
        0 => 'ground',
        1 => 'felling',
        2 => 'maintenance',
      ),
      'level' => 'all',
      'brand_path' => '/husqvarna/',
      'photo' => 
      array (
        'src' => '/assets/photos/chain-bar-2.webp',
        'sm' => '/assets/photos/chain-bar-2-sm.webp',
        'title' => '20160823-FS-LSC-0474',
        'creator' => 'USDAgov',
        'creator_url' => 'https://www.flickr.com/photos/41284017@N08',
        'license' => 'Public domain',
        'license_url' => 'https://creativecommons.org/publicdomain/mark/1.0/',
        'source_url' => 'https://www.flickr.com/photos/41284017@N08/28725898983',
