    '/jobsite/power-equipment/parts/husqvarna-anti-vibration-element-assembly-for-550xp-mark-ii/' => 
    array (
      'path' => '/jobsite/power-equipment/parts/husqvarna-anti-vibration-element-assembly-for-550xp-mark-ii/',
      'category' => '/jobsite/power-equipment/parts/',
      'name' => 'Husqvarna Anti-Vibration Element Assembly for 550XP Mark II',
      'brand' => 'husqvarna',
