    '/jobsite/power-equipment/parts/husqvarna-anti-vibration-element-for-572xp/' => 
    array (
      'path' => '/jobsite/power-equipment/parts/husqvarna-anti-vibration-element-for-572xp/',
      'category' => '/jobsite/power-equipment/parts/',
      'name' => 'Husqvarna Anti-Vibration Element for 572XP',
      'brand' => 'husqvarna',
      'brand_name' => 'Husqvarna',
