    '/jobsite/power-equipment/parts/husqvarna-choke-control-stop-for-562xp/' => 
    array (
      'path' => '/jobsite/power-equipment/parts/husqvarna-choke-control-stop-for-562xp/',
      'category' => '/jobsite/power-equipment/parts/',
      'name' => 'Husqvarna Choke Control Stop for 562XP',
      'brand' => 'husqvarna',
