    '/jobsite/power-equipment/parts/husqvarna-micro-switch-safety-switch-for-t540ixp-battery-saw/' => 
    array (
      'path' => '/jobsite/power-equipment/parts/husqvarna-micro-switch-safety-switch-for-t540ixp-battery-saw/',
      'category' => '/jobsite/power-equipment/parts/',
