    '/jobsite/power-equipment/parts/husqvarna-screw-for-395xp-muffler-support/' => 
    array (
      'path' => '/jobsite/power-equipment/parts/husqvarna-screw-for-395xp-muffler-support/',
      'category' => '/jobsite/power-equipment/parts/',
      'name' => 'Husqvarna Screw for 395XP Muffler Support',
