    '/jobsite/power-equipment/parts/muffler-for-husqvarna-562xp-chainsaw/' => 
    array (
      'path' => '/jobsite/power-equipment/parts/muffler-for-husqvarna-562xp-chainsaw/',
      'category' => '/jobsite/power-equipment/parts/',
      'name' => 'Muffler for Husqvarna 562XP Chainsaw',
      'brand' => 'husqvarna',
