    '/jobsite/power-equipment/parts/replacement-screw-for-husqvarna-395xp-muffler/' => 
    array (
      'path' => '/jobsite/power-equipment/parts/replacement-screw-for-husqvarna-395xp-muffler/',
      'category' => '/jobsite/power-equipment/parts/',
      'name' => 'Replacement Screw for Husqvarna 395XP Muffler',
      'brand' => 'husqvarna',
      'brand_name' => 'Husqvarna',
