    '/plant-care/cabling-and-bracing/cabling-hardware/ammon-eye-nut/' => 
    array (
      'path' => '/plant-care/cabling-and-bracing/cabling-hardware/ammon-eye-nut/',
      'category' => '/plant-care/cabling-and-bracing/cabling-hardware/',
      'name' => 'Amon Eye Nut',
      'brand' => 'gap',
      'brand_name' => 'Gap Arborist Supply',
      'kind' => 'cable-hardware',
      'price' => 10,
      'keyword' => 'amon eye nut',
      'title' => 'Amon Eye Nut for Tree Cabling Threaded Rod',
      'h1' => 'Amon Eye Nut',
      'meta' => 'Amon eye nut for tree cabling. It threads onto rod or a bolt end to give a forged eye for cable attachment, turning threaded rod into a strong through anchor.',
      'tagline' => 'A forged eye nut that turns threaded rod into a cable anchor point.',
      'summary' => 'An Amon eye nut threads onto threaded rod or a bolt end to give a forged eye for cable attachment. It is a classic way to build through-hardware anchors in tree cabling, cut to length on site.',
      'highlights' => 
      array (
        0 => 'Forged eye that threads onto rod',
        1 => 'Builds a through anchor cut to stem length',
        2 => 'Seats against a washer on the bark',
        3 => 'Match the thread size to your rod',
        4 => 'Galvanized for outdoor use',
      ),
      'specs' => 
      array (
        0 => 
        array (
          0 => 'Type',
          1 => 'Amon eye nut',
        ),
        1 => 
        array (
          0 => 'Use',
          1 => 'Cable anchor on threaded rod or bolts',
        ),
        2 => 
        array (
          0 => 'Sizes',
          1 => 'Select by rod thread size',
        ),
      ),
      'body' => 
      array (
        0 => 
        array (
          'h' => 'Why use an eye nut',
          'p' => 
          array (
            0 => 'Eye bolts come in fixed lengths. With threaded rod and an Amon eye nut you can build an anchor to exactly the length a stem needs. The rod goes through the leader, a washer and the eye nut go on the cable side, and a washer and nut hold the far end.',
            1 => 'Thread size must match the rod. Thread the eye nut on fully so it seats against the washer, and set the eye in line with the direction of the cable.',
            2 => 'An eye nut on threaded rod also lets you fine-tune where the eye sits relative to the bark, which helps keep the eye close to the stem without being buried. Keep a mix of rod lengths and eye nuts in the kit so you are ready for stems of different sizes.',
          ),
        ),
        1 => 
        array (
          'h' => 'Install and inspect',
          'p' => 
          array (
            0 => 'Use galvanized, forged hardware rated for the system, drill the hole per ANSI A300 Part 3, and fit a thimble where the cable runs through the eye. Trim excess rod so it does not stick out far. Inspect for corrosion and wood decay around the hardware over time. Cabling and bracing is structural work on a living tree. It should be specified and installed by a trained arborist following ANSI A300 Part 3, ANSI Z133 and the hardware maker\'s instructions, and inspected on a regular schedule after install. See more parts in our <a href="/plant-care/cabling-and-bracing/cabling-hardware/">cabling hardware</a> section.',
          ),
        ),
      ),
      'faq' => 
      array (
        0 => 
        array (
          'q' => 'Is it spelled Amon or Ammon?',
          'a' => 'Both spellings are used in catalogs. They refer to the same type of forged eye nut.',
        ),
        1 => 
        array (
          'q' => 'What rod do I use with it?',
          'a' => 'Galvanized threaded rod with a matching thread size, cut to suit the stem diameter.',
        ),
      ),
      'use' => 
      array (
        0 => 'plant-health',
      ),
      'level' => 'pro',
      'brand_path' => '/gap-arborist-supply/',
      'photo' => 
      array (
        'src' => '/assets/photos/cable-hardware-4.webp',
        'sm' => '/assets/photos/cable-hardware-4-sm.webp',
        'title' => 'Project 365 #278: 051011 Going Nuts',
        'creator' => 'comedy_nose',
        'creator_url' => 'https://www.flickr.com/photos/23408922@N07',
        'license' => 'Public domain',
        'license_url' => 'https://creativecommons.org/publicdomain/mark/1.0/',
        'source_url' => 'https://www.flickr.com/photos/23408922@N07/6214688085',
      ),
    ),
    '/plant-care/cabling-and-bracing/cabling-hardware/galvanized-flat-washer/' => 
    array (
      'path' => '/plant-care/cabling-and-bracing/cabling-hardware/galvanized-flat-washer/',
      'category' => '/plant-care/cabling-and-bracing/cabling-hardware/',
      'name' => 'Galvanized Flat Washer',
      'brand' => 'gap',
      'brand_name' => 'Gap Arborist Supply',
      'kind' => 'cable-hardware',
      'price' => 2,
      'keyword' => 'galvanized flat washer',
      'title' => 'Galvanized Flat Washer for Tree Cabling Hardware',
      'h1' => 'Galvanized Flat Washer',
      'meta' => 'Galvanized flat washer for tree cabling and bracing hardware. It spreads nut and eye load across the wood and resists rust on hardware left in the tree.',
      'tagline' => 'Galvanized washers to seat nuts and eyes on through-bolted cabling hardware.',
      'summary' => 'A galvanized flat washer sits under the nut or eye of cabling and bracing hardware to spread the load over the wood. The galvanized finish holds up outdoors, which matters for hardware that stays in a tree for years.',
      'highlights' => 
      array (
        0 => 'Galvanized for outdoor use',
        1 => 'Spreads nut and eye load over the wood',
        2 => 'Used on through-bolted cabling and bracing',
        3 => 'Match the hole size to your hardware',
        4 => 'Keep a supply in the cabling kit',
      ),
      'specs' => 
      array (
        0 => 
        array (
          0 => 'Type',
          1 => 'Flat washer',
        ),
        1 => 
        array (
          0 => 'Finish',
          1 => 'Galvanized',
        ),
        2 => 
        array (
          0 => 'Sizes',
          1 => 'Select to match hardware diameter',
        ),
      ),
      'body' => 
      array (
        0 => 
        array (
          'h' => 'What washers do in cabling',
          'p' => 
          array (
            0 => 'Through hardware needs something between the nut or eye and the tree. A washer spreads the clamping load so the nut does not crush into the bark and wood. On rounded stems, many installers use a beveled or curved washer where it seats better, and a flat washer where the surface allows.',
            1 => 'Match the washer\'s hole to the hardware diameter. A washer with an oversized hole lets the nut pull into it and defeats the point.',
            2 => 'Buy washers in quantity, since every through-bolt anchor needs at least one and they are easy to drop. Keeping a jar of matched washers and nuts for each hardware size in the cabling kit saves a lot of searching and makes sure the right parts go in the tree.',
          ),
        ),
        1 => 
        array (
          'h' => 'Install and inspect',
          'p' => 
          array (
            0 => 'Seat the washer against the bark without cutting away more than needed, and snug the nut firmly. Mixed metals can corrode, so keep to galvanized hardware throughout the system. Check washers and nuts at each inspection for rust, loosening and wood growth over the hardware. Cabling and bracing is structural work on a living tree. It should be specified and installed by a trained arborist following ANSI A300 Part 3, ANSI Z133 and the hardware maker\'s instructions, and inspected on a regular schedule after install. See more in our <a href="/plant-care/cabling-and-bracing/cabling-hardware/">cabling hardware</a> section.',
          ),
        ),
      ),
      'faq' => 
      array (
        0 => 
        array (
          'q' => 'Flat washer or beveled washer?',
          'a' => 'Use whichever seats better on the stem. Beveled or curved washers suit rounded surfaces; flat washers suit flatter spots.',
        ),
        1 => 
        array (
          'q' => 'Why galvanized?',
          'a' => 'Cabling hardware stays outdoors for years. Galvanizing slows corrosion and matches other galvanized hardware in the system.',
        ),
      ),
      'use' => 
      array (
        0 => 'plant-health',
      ),
      'level' => 'all',
      'brand_path' => '/gap-arborist-supply/',
      'photo' => 
      array (
        'src' => '/assets/photos/cable-hardware-5.webp',
        'sm' => '/assets/photos/cable-hardware-5-sm.webp',
        'title' => 'Eye bolt snow bokeh',
        'creator' => 'dsgetch',
        'creator_url' => 'https://www.flickr.com/photos/66136677@N00',
        'license' => 'CC BY 2.0',
        'license_url' => 'https://creativecommons.org/licenses/by/2.0/',
        'source_url' => 'https://www.flickr.com/photos/66136677@N00/51782009502',
      ),
    ),
    '/plant-care/cabling-and-bracing/cabling-hardware/preformed-line-products-dead-end-cable-grips/' => 
    array (
      'path' => '/plant-care/cabling-and-bracing/cabling-hardware/preformed-line-products-dead-end-cable-grips/',
      'category' => '/plant-care/cabling-and-bracing/cabling-hardware/',
      'name' => 'Preformed Line Products Dead-End Cable Grips',
      'brand' => 'preformed-line-products',
      'brand_name' => 'Preformed Line Products',
      'kind' => 'cable-hardware',
      'price' => 8,
      'keyword' => 'dead-end cable grips',
      'title' => 'Preformed Line Products Dead-End Cable Grips',
      'h1' => 'Preformed Line Products Dead-End Cable Grips',
      'meta' => 'Preformed Line Products dead-end cable grips terminate steel strand by wrapping it with helical rods. A fast, tidy way to finish a tree cable at the anchor eye.',
      'tagline' => 'Helical dead-ends for fast, clean termination of steel support cable.',
      'summary' => 'Preformed Line Products dead-end cable grips terminate steel strand with helically formed rods that wrap around the cable. In tree cabling they make a quick, tidy termination at the anchor eye.',
      'highlights' => 
      array (
        0 => 'Helical-wrap termination for steel strand',
        1 => 'Fast to install with no clamps or splices',
        2 => 'Sized to a specific cable diameter',
        3 => 'Widely used in utility and tree cabling',
        4 => 'Use with a thimble at the anchor eye',
      ),
      'specs' => 
      array (
        0 => 
        array (
          0 => 'Brand',
          1 => 'Preformed Line Products',
        ),
        1 => 
        array (
          0 => 'Type',
          1 => 'Helical dead-end grip',
        ),
        2 => 
        array (
          0 => 'Sizes',
          1 => 'Match to cable diameter and type',
        ),
      ),
      'body' => 
      array (
        0 => 
        array (
          'h' => 'How dead-end grips work',
          'p' => 
          array (
            0 => 'A dead-end grip is a set of preformed helical rods. You loop it around a thimble in the anchor eye and wrap both legs onto the cable. The helix grips the strand along its length, spreading the load without clamps or hand splices.',
            1 => 'Each grip is made for a specific cable diameter and type. A grip on the wrong size cable will not hold its rated load. Check the color code or marking on the grip against the cable you are installing.',
            2 => 'Dead-end grips have become common in tree cabling because they are quick to install aloft and do not depend on the installer\'s splicing skill. They do still need to be applied correctly, so practice on the ground before using them in a tree.',
          ),
        ),
        1 => 
        array (
          'h' => 'Install and inspect',
          'p' => 
          array (
            0 => 'Use a thimble at the eye, wrap the legs fully onto the cable and do not reuse grips once they have been applied and removed unless the maker allows it. Leave enough cable tail as the instructions show. Inspect at each check for corrosion, slipping and wear at the eye. Cabling and bracing is structural work on a living tree. It should be specified and installed by a trained arborist following ANSI A300 Part 3, ANSI Z133 and the hardware maker\'s instructions, and inspected on a regular schedule after install. Find the rest of the hardware in our <a href="/plant-care/cabling-and-bracing/cabling-hardware/">cabling hardware</a> section.',
          ),
        ),
      ),
      'faq' => 
      array (
        0 => 
        array (
          'q' => 'Can I reuse a dead-end grip?',
          'a' => 'Follow the maker\'s instructions. Many helical dead-ends are not meant to be reused after they have been removed.',
        ),
        1 => 
        array (
          'q' => 'Do I need a thimble?',
          'a' => 'Yes, a thimble at the anchor eye protects the grip and cable from a sharp bend and wear.',
        ),
      ),
      'use' => 
      array (
        0 => 'plant-health',
      ),
      'level' => 'pro',
      'brand_path' => '/preformed-line-products/',
      'photo' => 
      array (
        'src' => '/assets/photos/cable-hardware-0.webp',
        'sm' => '/assets/photos/cable-hardware-0-sm.webp',
        'title' => 'Eye Bolt - Basil Watson\'s Sopwith-Type Biplane, Melbourne, Victoria, 1916',
        'creator' => 'Photographer: David Thompson',
        'creator_url' => '',
        'license' => 'CC BY 4.0',
        'license_url' => 'https://creativecommons.org/licenses/by/4.0/',
        'source_url' => 'https://collections.museumsvictoria.com.au/items/393624',
      ),
