    '/rigging/rigging-slings/ring-slings/3-4-dead-eye-ring-sling-x-15/' => 
    array (
      'path' => '/rigging/rigging-slings/ring-slings/3-4-dead-eye-ring-sling-x-15/',
      'category' => '/rigging/rigging-slings/heavy-duty-slings/',
      'name' => '3/4 in. Dead-Eye Ring Sling, 15 ft',
      'brand' => 'gap',
      'brand_name' => 'Gap Arborist Supply',
