    '/rigging/rigging-slings/ring-slings/dead-eye-ring-sling-with-beast-ring/' => 
    array (
      'path' => '/rigging/rigging-slings/ring-slings/dead-eye-ring-sling-with-beast-ring/',
      'category' => '/rigging/rigging-slings/heavy-duty-slings/',
