    '/safety/eye-protection/kask-zenith-zen-visor-carrier/' => 
    array (
      'path' => '/safety/eye-protection/kask-zenith-zen-visor-carrier/',
      'category' => '/safety/eye-protection/',
      'name' => 'Kask Zenith Zen Visor Carrier',
