    '/safety/first-aid/weaver-orange-first-aid-pouch/' => 
    array (
      'path' => '/safety/first-aid/weaver-orange-first-aid-pouch/',
      'category' => '/safety/first-aid/',
      'name' => 'Weaver Orange First Aid Pouch',
      'brand' => 'weaver',
