    '/static-climbing-rope/yale-phantom-green-and-purple-11mm-climbing-rope/' => 
    array (
      'path' => '/static-climbing-rope/yale-phantom-green-and-purple-11mm-climbing-rope/',
      'category' => '/rope/climbing-rope/static-climbing-rope/',
