    '/clothing/tree-climbing-pants/arborwear-after-hours-belt-chain-design/' => 
    array (
      'path' => '/clothing/tree-climbing-pants/arborwear-after-hours-belt-chain-design/',
      'category' => '/clothing/tree-climbing-pants/',
      'name' => 'Arborwear After Hours Belt (Chain Design)',
      'brand' => 'arborwear',
