    '/climbing/climbing-gear/friction-savers/teufelberger-fimblsaver/' => 
    array (
      'path' => '/climbing/climbing-gear/friction-savers/teufelberger-fimblsaver/',
      'category' => '/climbing/climbing-gear/friction-savers/',
      'name' => 'Teufelberger fimblSAVER',
      'brand' => 'teufelberger',
