    '/climbing/climbing-gear/gear-storage/throw-line-storage/weaver-nesting-throwline-storage-bag/' => 
    array (
      'path' => '/climbing/climbing-gear/gear-storage/throw-line-storage/weaver-nesting-throwline-storage-bag/',
      'category' => '/climbing/climbing-gear/gear-storage/',
