    '/climbing/saddles-and-harnesses/weaver-saddles/weaver-wlc-530-climbing-saddle/' => 
    array (
      'path' => '/climbing/saddles-and-harnesses/weaver-saddles/weaver-wlc-530-climbing-saddle/',
      'category' => '/climbing/saddles-and-harnesses/',
      'name' => 'Weaver WLC-530 Climbing Saddle',
      'brand' => 'weaver',
      'brand_name' => 'Weaver',
