    '/climbing/spurs/aluminum-spurs/tree-hog-aluminum-climbers-with-soft-cushion-pads/' => 
    array (
      'path' => '/climbing/spurs/aluminum-spurs/tree-hog-aluminum-climbers-with-soft-cushion-pads/',
      'category' => '/climbing/spurs/aluminum-spurs/',
      'name' => 'Tree Hog Aluminum Climbers with Soft Cushion Pads',
      'brand' => 'tree-hog',
