    '/climbing/spurs/climber-pads/weaver-l-shaped-climber-pads/' => 
    array (
      'path' => '/climbing/spurs/climber-pads/weaver-l-shaped-climber-pads/',
      'category' => '/climbing/spurs/climber-pads/',
