    '/climbing/spurs/straps/weaver-brahma-webb-lower-climber-straps/' => 
    array (
      'path' => '/climbing/spurs/straps/weaver-brahma-webb-lower-climber-straps/',
      'category' => '/climbing/spurs/replacement-gaffs-and-parts/',
      'name' => 'Weaver Brahma Webb Lower Climber Straps',
      'brand' => 'weaver',
