    '/cutting-and-pruning/pruners-and-loppers/jameson-ja-14-fixed-pulley-pruner-kit/' => 
    array (
      'path' => '/cutting-and-pruning/pruners-and-loppers/jameson-ja-14-fixed-pulley-pruner-kit/',
      'category' => '/cutting-and-pruning/pruners-and-loppers/',
      'name' => 'Jameson JA-14 Fixed Pulley Pruner Kit',
      'brand' => 'jameson',
      'brand_name' => 'Jameson',
