    '/rope/climbing-rope/16-strand-climbing-rope/courant-komora-climbing-rope/' => 
    array (
      'path' => '/rope/climbing-rope/16-strand-climbing-rope/courant-komora-climbing-rope/',
      'category' => '/rope/climbing-rope/16-strand-climbing-rope/',
      'name' => 'Courant Komora Climbing Rope',
      'brand' => 'courant',
