    '/shop-all/11mm-replacement-rope-bridge-kmiii-max-black-and-yellow/' => 
    array (
      'path' => '/shop-all/11mm-replacement-rope-bridge-kmiii-max-black-and-yellow/',
      'category' => '/climbing/saddles-and-harnesses/saddle-parts-and-shoulder-harnesses/',
