        8 => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-chain/husqvarna-h57s-404-x-063-semi-chisel-square-chisel-chain/',
        9 => '/jobsite/chainsaw-accessories/chainsaw-bars-and-chain/chainsaw-chain/husqvarna-325-mini-x-043-chainsaw-chain/',
