        4 => '/jobsite/chainsaw-accessories/chaps-and-protective-gear/chainsaw-pants/clogger-zero-gen-2-chainsaw-pants/',
        5 => '/shop-all/clogger-zero-light-and-cool-ul-chainsaw-chaps-apron-style/',
