        8 => '/chainsaw-pants/arbortec-breatheflex-pro-realtree-camo-pants-lime-green/',
        9 => '/jobsite/chainsaw-accessories/chaps-and-protective-gear/chainsaw-pants/arbortec-black-breatheflex-pro-chainsaw-pants/',
        10 => '/jobsite/chainsaw-accessories/chaps-and-protective-gear/chainsaw-pants/arbortec-blue-breatheflex-pro-chainsaw-pants/',
        11 => '/shop-all/arbortec-breatheflex-pro-class-c-chainsaw-pants-black/',
        12 => '/chainsaw-pants/arbortec-patriot-breatheflex-pro-chainsaw-pants/',
        13 => '/chainsaw-pants/clogger-ascend-gen-2-chainsaw-pants-hcb-edition/',
        14 => '/chainsaw-pants/cloggertreecrew-mens-chainsaw-pants/',
        15 => '/jobsite/chainsaw-accessories/chaps-and-protective-gear/chainsaw-pants/clogger-ascend-gen-2-chainsaw-pants/',
        16 => '/jobsite/chainsaw-accessories/chaps-and-protective-gear/chainsaw-pants/clogger-ember-chainsaw-pants/',
      ),
      'photo' => 
      array (
        'src' => '/assets/photos/chaps-pants-1.webp',
        'sm' => '/assets/photos/chaps-pants-1-sm.webp',
        'title' => 'Chainsaw Safety',
        'creator' => 'KSRE Photo',
        'creator_url' => 'https://www.flickr.com/photos/43276854@N02',
        'license' => 'CC BY 2.0',
        'license_url' => 'https://creativecommons.org/licenses/by/2.0/',
