        6 => '/safety/communication/sena-tufftalk-lite-helmet-mounted-earmuffs/',
        7 => '/safety/communication/bump-cap-for-sena-smh-10/',
        8 => '/safety/communication/sena-communication-spare-parts-kit/',
        9 => '/safety/communication/sena-crane-operator-headset/',
        10 => '/shop-all/husqvarna-x-com-active-headband-style-communication-system/',
      ),
      'photo' => 
      array (
        'src' => '/assets/photos/helmet-0.webp',
        'sm' => '/assets/photos/helmet-0-sm.webp',
        'title' => 'Arches Canyoneering',
        'creator' => 'ArchesNPS',
        'creator_url' => 'https://www.flickr.com/photos/72578886@N08',
