      array (
        0 => '/clothing/arborist-boots/arbortec-scafell-lite-chainsaw-boots-lime-green/',
        1 => '/clothing/tree-climbing-pants/heavy-duty-suspenders-for-chainsaw-pants-by-arbortec/',
        2 => '/chainsaw-pants/arbortec-breatheflex-pro-realtree-camo-chainsaw-pants-brown/',
